import{z as i,x as s,o as r,c as B,q as o,j as l,D as e,d as E,s as t,S as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"GaLore","description":"","frontmatter":{"title":"GaLore","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/galore.md","filePath":"llm/galore.md","lastUpdated":1791413859000}'),m={name:"llm/galore.md"};function d(p,a,h,D,_,L){const A=s("Mermaid");return r(),B("div",null,[a[2]||(a[2]=o('<h1 id="galore" tabindex="-1">GaLore <a class="header-anchor" href="#galore" aria-label="Permalink to &quot;GaLore&quot;">​</a></h1><div class="epigraph"><p>可以不把权重限制在低秩，而把**梯度**投影到低秩子空间里再写 Adam；全参轨迹的显存就能降到接近适配器训练。</p><footer>—— Zhao 等，GaLore: Memory-Efficient LLM Training by Gradient Low-Rank Projection，ICML 2024</footer></div><p><a href="/llm/vera">VeRA</a> 与 <a href="/llm/lora">LoRA</a> 都限制<strong>权重增量</strong>的秩。若任务其实需要满秩更新——<a href="/llm/lora-vs-full-lr">学习率课</a>里 Biderman 等人说 LoRA 学得少——缺口就是：全参的 Adam 状态仍是 2× 参数量。Zhao、Zhang 等人的 GaLore 对梯度做周期低秩投影，\\(W\\) 仍满秩可写，优化器状态按投影秩存。本课写「低秩梯度 ≠ 低秩权重」。不把逐层冻结（<a href="/llm/lisa-layerwise">下一课 LISA</a>）写成同一算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全参 SFT / 继续预训练的显存四件套：权重、梯度、Adam 一阶二阶、激活。LoRA 砍掉后三项的主体，却把 \\(\\Delta W\\) 锁在 \\(BA\\) 里。有些设定（从预训练中段继续、领域 DAPT、需要高秩改写）LoRA 天花板明显。希望：权重保持 \\(d_{\\mathrm{out}}\\times d_{\\mathrm{in}}\\) 的自由度，但不要为每个元素存两份 Adam。</p><p>观察是：训练中一段时间内，梯度矩阵 \\(G\\) 的能量集中在少数奇异方向上。若每隔 \\(T\\) 步对 \\(G\\) 做一次截断 SVD，把 Adam 跑在投影后的低秩系数上，再映回满空间更新 \\(W\\)，则优化器状态与 \\(r(d_{\\mathrm{in}}+d_{\\mathrm{out}})\\) 同阶，而 \\(W\\) 仍能随投影基的更换积累<strong>高秩</strong>变化。</p><h3 id="投影的是梯度-不是冻结随机-a、b" tabindex="-1">投影的是梯度，不是冻结随机 A、B <a class="header-anchor" href="#投影的是梯度-不是冻结随机-a、b" aria-label="Permalink to &quot;投影的是梯度，不是冻结随机 A、B&quot;">​</a></h3><p>VeRA 的随机矩阵不随数据变。GaLore 的投影基来自当前梯度的主成分，定期刷新。LoRA 学的是权重因子；GaLore 不引入适配器模块，前向仍是稠密 \\(Wx\\)。</p><p><span class="marginnote">论文在预训练与微调上都做了记忆对比：强调可接近全参质量、显存显著低于 8-bit Adam 全状态。它不是量化方法；可与量化叠，但本课只讲投影。</span></p><p><span class="marginnote">「Adam 一阶二阶状态」翻译一下：Adam 要为每个参数存两份表——动量（一阶）与二阶矩，各与参数同形。7B 模型这两份以 16-bit 存就要约 28 GB，比权重本身还占地方；GaLore 省的主要就是这笔，办法是只给投影后的低秩系数配 Adam。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对选定线性层的梯度 \\(G_t\\)，每隔 \\(T\\) 步计算秩-\\(r\\) 近似（例如左奇异向量 \\(P\\)），在窗口内用 \\(P^\\top G\\) 作为优化器输入，Adam 状态与投影系数同形，更新再乘回 \\(P\\)。\\(r\\) 与 \\(T\\) 是主超参：\\(r\\) 过小截掉有用梯度，\\(T\\) 过长则投影基过期、\\(T\\) 过短则 SVD 太贵。嵌入与范数层可排除在投影外，以免词表更新被过度压缩。</p><p>学习率按<strong>全参</strong>逻辑取（\\(10^{-5}\\) 量级做 SFT，\\(10^{-4}\\) 量级做预训练段），不要用 LoRA 的 \\(10^{-4}\\) SFT 默认——参数化是满 \\(W\\)。SFT 仍遵守<a href="/llm/response-only-loss">仅回复</a>与<a href="/llm/chat-template">模板</a>。</p>',13)),(r(),l(n,null,{default:e(()=>[t(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%A8%A0%E5%AF%86%E5%89%8D%E5%90%91%20W%22%5D%20--%3E%20G%5B%22%E6%BB%A1%E6%A2%AF%E5%BA%A6%20G%22%5D%0A%20%20G%20--%3E%20SVD%5B%22%E6%AF%8F%20T%20%E6%AD%A5%EF%BC%9A%E4%BD%8E%E7%A7%A9%E6%8A%95%E5%BD%B1%E5%9F%BA%22%5D%0A%20%20SVD%20--%3E%20AD%5B%22Adam%20%E5%9C%A8%E6%8A%95%E5%BD%B1%E7%B3%BB%E6%95%B0%E4%B8%8A%22%5D%0A%20%20AD%20--%3E%20W2%5B%22%E6%BB%A1%E7%A7%A9%E7%B4%AF%E5%8A%A0%E5%88%B0%20W%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>实现要注意与分布式分片一致：投影在每张分片矩阵上局部做，还是聚集后再做，会影响秩的含义。配方应写清。</p><p><span class="marginnote">给个数代入状态量：\\(4096 \\times 4096\\) 的层，Adam 全状态约 1677 万元素；取秩 \\(r=128\\) 时，投影系数只有 \\(128 \\times (4096+4096) \\approx 105\\) 万元素，缩到约 1/16。\\(r\\) 每翻一倍，这笔账就翻一倍——显存与表达力的换挡杆就是它。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窗口内，更新被限制在当前 \\(P\\) 的列空间，这一段轨迹低秩；窗口切换后 \\(P\\) 变了，新的方向被打开，\\(W\\) 的总变化可以满秩。这与 <a href="/llm/relora">ReLoRA</a>「合并 LoRA 再重置」是亲戚：都用时间换秩，但 ReLoRA 改的是适配器，GaLore 改的是优化器坐标系。</p><p>若真实梯度一直满秩且能量均匀，截断 SVD 会系统性地丢掉一部分更新，收敛慢或偏。指令 SFT 上梯度往往更低秩，GaLore 更舒服；要从随机初始化预训练，需更大 \\(r\\) 或更勤的刷新。</p><p><span class="marginnote">rsLoRA 的 γ 与 GaLore 无关。不要给 GaLore 再乘一份 α/r。显存省在 Adam 状态，不省在权重存储——检查点仍是满 W。</span></p>',6)),(r(),l(n,null,{default:e(()=>[t(A,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20W1%5B%22%E7%AA%97%E5%8F%A3%201%EF%BC%9A%E6%8A%95%E5%BD%B1%E5%9F%BA%20P1%22%5D%20--%3E%20L1%5B%22%E6%9C%AC%E7%AA%97%E5%8F%A3%E6%9B%B4%E6%96%B0%E8%A2%AB%E9%99%90%E5%9C%A8%20P1%20%E5%88%97%E7%A9%BA%E9%97%B4%EF%BC%88%E4%BD%8E%E7%A7%A9%EF%BC%89%22%5D%0A%20%20L1%20--%3E%20REF%5B%22%E6%AF%8F%20T%20%E6%AD%A5%E5%88%B7%E6%96%B0%EF%BC%9ASVD%20%E5%BD%93%E5%89%8D%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20REF%20--%3E%20W2%5B%22%E7%AA%97%E5%8F%A3%202%EF%BC%9A%E6%96%B0%E5%9F%BA%20P2%EF%BC%8C%E6%89%93%E5%BC%80%E6%96%B0%E6%96%B9%E5%90%91%22%5D%0A%20%20W2%20--%3E%20L2%5B%22%E5%8F%88%E6%98%AF%E4%BD%8E%E7%A7%A9%EF%BC%8C%E4%BD%86%E6%96%B9%E5%90%91%E4%B8%8D%E5%90%8C%22%5D%0A%20%20L2%20--%3E%20SUM%5B%22%E6%97%B6%E9%97%B4%E4%B8%8A%E7%B4%AF%E5%8A%A0%EF%BC%9A%E6%80%BB%E5%8F%98%E5%8C%96%E5%8F%AF%E6%BB%A1%E7%A7%A9%22%5D%0A%20%20SUM%20--%3E%7C%22%E7%BB%A7%E7%BB%AD%E8%AE%AD%E7%BB%83%22%7C%20REF%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">初学者容易以为投影会把权重永远锁死在低秩里——实际上单个窗口内低秩、窗口之间基在换，时间上累积起来可以满秩。真正的风险不在秩，而在真实梯度能量分散（一直满秩）时，截断 SVD 会系统性地丢掉一部分更新，表现为收敛变慢。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>推理与全参相同，没有适配器可切换任务。多任务仍要存多份 \\(W\\) 或差分。SVD 周期在超大层上有计算开销，需摊进吞吐。激活显存仍在，长上下文下 GaLore 救不了注意力二次方，那是<a href="/llm/long-context-finetune">长微调课</a>的问题。</p><p>与 QLoRA 比：QLoRA 冻结量化基座；GaLore 训练满精度（或混合精度）稠密权重。目标相反。需要一份可合并的小适配器时用 LoRA/VeRA；需要接近全参的继续预训练显存方案时用 GaLore。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GaLore 将梯度低秩投影后跑 Adam，\\(W\\) 仍满秩，优化器状态按 \\(r\\) 存。</li><li>周期刷新投影基，使时间上可积累高秩更新。</li><li>学习率按全参，不按 LoRA。</li><li>检查点体积仍是满模型；省的是训练时优化器显存。</li><li>梯度并非总是低秩；预训练与微调的 \\(r\\)、\\(T\\) 不能照抄。</li><li>出处：Zhao 等，GaLore，ICML 2024。</li></ul>',6))])}const f=i(m,[["render",d]]);export{T as __pageData,f as default};
